<?php
if(session_status()!==PHP_SESSION_ACTIVE) session_start();
function ap_db(){static $p;if($p)return $p;$p=new PDO('mysql:host='.(getenv('DB_HOST')?:'127.0.0.1').';port='.(getenv('DB_PORT')?:'3306').';dbname='.(getenv('DB_NAME')?:'datasell').';charset=utf8mb4',getenv('DB_USER')?:'root',getenv('DB_PASS')?:'',[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);return $p;}
function ap_e($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function ap_money($v){return '₦'.number_format((float)$v,2);}
if(empty($_SESSION['uid'])){header('Location:/?page=login');exit;}
$p=ap_db();$q=$p->prepare('SELECT id,fullname,admin_role,admin_permissions,admin_enabled FROM users WHERE id=?');$q->execute([$_SESSION['uid']]);$me=$q->fetch();
$perms=json_decode($me['admin_permissions']??'[]',true)?:[];$allowed=$me&&$me['admin_role']==='super_admin'||($me&&$me['admin_role']==='admin'&&(int)$me['admin_enabled']===1&&in_array('products',$perms,true));if(!$allowed){http_response_code(403);exit('403 Forbidden — Products & Pricing permission required.');}
if(empty($_SESSION['ap_csrf']))$_SESSION['ap_csrf']=bin2hex(random_bytes(24));$msg='';$err='';
if($_SERVER['REQUEST_METHOD']==='POST')try{if(!hash_equals($_SESSION['ap_csrf'],$_POST['csrf']??''))throw new Exception('Session expired. Refresh and try again.');$action=$_POST['action']??'';
 if($action==='save'){$id=(int)($_POST['id']??0);$cost=(float)($_POST['cost']??0);$retail=(float)($_POST['retail']??0);$reseller=(float)($_POST['reseller']??0);$api=(float)($_POST['api']??0);if(!$id)throw new Exception('Invalid product.');if(min($cost,$retail,$reseller,$api)<0)throw new Exception('Prices cannot be negative.');if($retail<$cost||$reseller<$cost||$api<$cost)throw new Exception('Selling prices cannot be below provider cost.');$s=$p->prepare('UPDATE service_plans SET cost_price=?,retail_price=?,reseller_price=?,api_price=?,price=? WHERE id=?');$s->execute([$cost,$retail,$reseller,$api,$retail,$id]);$msg='Product prices updated successfully.';}
 if($action==='toggle'){$id=(int)($_POST['id']??0);$p->prepare('UPDATE service_plans SET active=IF(active=1,0,1) WHERE id=?')->execute([$id]);$msg='Product availability updated.';}
}catch(Throwable $e){$err=$e->getMessage();}
$cat=trim($_GET['category']??'');$search=trim($_GET['q']??'');$sql='SELECT * FROM service_plans WHERE 1';$args=[];if($cat!==''){$sql.=' AND category=?';$args[]=$cat;}if($search!==''){$sql.=' AND (provider LIKE ? OR name LIKE ? OR code LIKE ?)';$like='%'.$search.'%';array_push($args,$like,$like,$like);}$sql.=' ORDER BY category,provider,sort_order,id';$s=$p->prepare($sql);$s->execute($args);$plans=$s->fetchAll();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Products & Pricing — IHLink Datasub</title><link rel="stylesheet" href="/assets/css/app.css?v=8"><link rel="stylesheet" href="/assets/css/admin-products.css?v=1"></head><body class="ap-body"><main class="ap-wrap"><header class="ap-head"><div><a href="/?page=admin" class="ap-back">← Admin Console</a><h1>Products & Pricing</h1><p>Edit provider cost and selling prices. Changes apply to future purchases.</p></div><div class="ap-user"><b><?=ap_e($me['fullname'])?></b><small><?=ap_e(str_replace('_',' ',ucwords($me['admin_role'],'_')))?></small></div></header><?php if($msg):?><div class="ap-alert success"><?=ap_e($msg)?></div><?php endif;?><?php if($err):?><div class="ap-alert error"><?=ap_e($err)?></div><?php endif;?><form class="ap-filter" method="get"><input name="q" value="<?=ap_e($search)?>" placeholder="Search product, provider or code"><select name="category"><option value="">All categories</option><?php foreach(['data','airtime','cable','electricity','exam'] as $c):?><option value="<?=$c?>" <?=$cat===$c?'selected':''?>><?=ucfirst($c)?></option><?php endforeach;?></select><button>Filter</button><a href="/admin-products.php">Reset</a></form><section class="ap-card"><div class="ap-table-wrap"><table><thead><tr><th>Product</th><th>Provider Cost</th><th>Retail</th><th>Reseller</th><th>API</th><th>Margin</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($plans as $r):?><tr><td><b><?=ap_e($r['provider'].' '.$r['name'])?></b><small><?=ap_e($r['category'].' · '.$r['code'])?></small></td><td><?=ap_money($r['cost_price'])?></td><td><?=ap_money($r['retail_price'])?></td><td><?=ap_money($r['reseller_price'])?></td><td><?=ap_money($r['api_price'])?></td><td><?=ap_money((float)$r['retail_price']-(float)$r['cost_price'])?></td><td><span class="ap-status <?=$r['active']?'on':'off'?>"><?=$r['active']?'Active':'Disabled'?></span></td><td><button type="button" class="ap-edit" data-id="<?=$r['id']?>" data-product="<?=ap_e($r['provider'].' '.$r['name'])?>" data-cost="<?=$r['cost_price']?>" data-retail="<?=$r['retail_price']?>" data-reseller="<?=$r['reseller_price']?>" data-api="<?=$r['api_price']?>">Edit Price</button><form method="post" class="ap-inline"><input type="hidden" name="csrf" value="<?=ap_e($_SESSION['ap_csrf'])?>"><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="ap-toggle"><?=$r['active']?'Disable':'Enable'?></button></form></td></tr><?php endforeach;?></tbody></table></div></section></main><dialog id="editDialog" class="ap-dialog"><form method="post" class="ap-modal"><input type="hidden" name="csrf" value="<?=ap_e($_SESSION['ap_csrf'])?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" id="ep-id"><div class="ap-modal-head"><div><small>EDIT PRODUCT</small><h2 id="ep-name">Product</h2></div><button type="button" id="ep-close">×</button></div><div class="ap-price-grid"><label>Provider Cost<input type="number" min="0" step="0.01" name="cost" id="ep-cost" required></label><label>Retail Price<input type="number" min="0" step="0.01" name="retail" id="ep-retail" required></label><label>Reseller Price<input type="number" min="0" step="0.01" name="reseller" id="ep-reseller" required></label><label>API Price<input type="number" min="0" step="0.01" name="api" id="ep-api" required></label></div><p class="ap-note">You can increase or reduce a price. Selling prices must remain at or above provider cost.</p><div class="ap-modal-actions"><button type="button" class="ap-cancel" id="ep-cancel">Cancel</button><button class="ap-save">Save Price Changes</button></div></form></dialog><script src="/assets/js/admin-products-page.js?v=1"></script></body></html>